type Value any

type OrderedMap struct {
	Entries []Entry
}

type Entry struct {
	Key   string
	Value Value
}

type InputDoc struct {
	FileIndex   int
	SourcePath  string
	InputFormat string
	Value       Value
}

func parseDocuments(data []byte, format string) ([]Value, error) {
	switch normalizeFormat(format) {
	case "yaml", "kyaml", "auto", "":
		return parseYAMLDocuments(data)
	case "json":
		val, err := parseJSONBytes(data)
		if err != nil {
			return nil, err
		}
		return []Value{val}, nil
	case "xml":
		val, err := parseXMLBytes(data)
		if err != nil {
			return nil, err
		}
		return []Value{val}, nil
	case "props":
		val, err := parsePropsBytes(data)
		if err != nil {
			return nil, err
		}
		return []Value{val}, nil
	case "ini":
		val, err := parseINIBytes(data)
		if err != nil {
			return nil, err
		}
		return []Value{val}, nil
	default:
		return nil, fmt.Errorf("unsupported input format: %s", format)
	}
}

func parseYAMLDocuments(data []byte) ([]Value, error) {
	dec := yaml.NewDecoder(bytes.NewReader(data))
	var docs []Value
	for {
		var node yaml.Node
		err := dec.Decode(&node)
		if err == io.EOF {
			break
		}
		if err != nil {
			return nil, err
		}
		if len(node.Content) == 0 {
			docs = append(docs, nil)
			continue
		}
		docs = append(docs, yamlNodeToValue(node.Content[0]))
	}
	return docs, nil
}

func yamlNodeToValue(node *yaml.Node) Value {
	switch node.Kind {
	case yaml.DocumentNode:
		if len(node.Content) == 0 {
			return nil
		}
		return yamlNodeToValue(node.Content[0])
	case yaml.MappingNode:
		obj := &OrderedMap{}
		for i := 0; i+1 < len(node.Content); i += 2 {
			key := node.Content[i].Value
			obj.Entries = append(obj.Entries, Entry{Key: key, Value: yamlNodeToValue(node.Content[i+1])})
		}
		return obj
	case yaml.SequenceNode:
		out := make([]Value, 0, len(node.Content))
		for _, child := range node.Content {
			out = append(out, yamlNodeToValue(child))
		}
		return out
	case yaml.ScalarNode:
		switch node.Tag {
		case "!!null":
			return nil
		case "!!bool":
			return strings.EqualFold(node.Value, "true")
		case "!!int":
			if v, err := strconv.ParseInt(node.Value, 10, 64); err == nil {
				return v
			}
		case "!!float":
			if v, err := strconv.ParseFloat(node.Value, 64); err == nil {
				return v
			}
		}
		return node.Value
	default:
		return nil
	}
}

func parseJSONBytes(data []byte) (Value, error) {
	dec := json.NewDecoder(bytes.NewReader(data))
	dec.UseNumber()
	val, err := parseJSONValue(dec)
	if err != nil {
		return nil, err
	}
	return val, nil
}

func parseJSONValue(dec *json.Decoder) (Value, error) {
	tok, err := dec.Token()
	if err != nil {
		return nil, err
	}
	switch t := tok.(type) {
	case json.Delim:
		switch t {
		case '{':
			obj := &OrderedMap{}
			for dec.More() {
				keyTok, err := dec.Token()
				if err != nil {
					return nil, err
				}
				key, ok := keyTok.(string)
				if !ok {
					return nil, fmt.Errorf("invalid object key")
				}
				val, err := parseJSONValue(dec)
				if err != nil {
					return nil, err
				}
				obj.Entries = append(obj.Entries, Entry{Key: key, Value: val})
			}
			_, err = dec.Token()
			return obj, err
		case '[':
			var arr []Value
			for dec.More() {
				val, err := parseJSONValue(dec)
				if err != nil {
					return nil, err
				}
				arr = append(arr, val)
			}
			_, err = dec.Token()
			return arr, err
		default:
			return nil, fmt.Errorf("unexpected delimiter: %v", t)
		}
	case string:
		return t, nil
	case bool:
		return t, nil
	case nil:
		return nil, nil
	case json.Number:
		if strings.ContainsAny(string(t), ".eE") {
			v, err := t.Float64()
			if err != nil {
				return nil, err
			}
			return v, nil
		}
		v, err := t.Int64()
		if err != nil {
			fv, ferr := t.Float64()
			if ferr != nil {
				return nil, ferr
			}
			return fv, nil
		}
		return v, nil
	default:
		return nil, fmt.Errorf("unsupported json token: %T", tok)
	}
}

