package main

import (
	"bytes"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"strconv"
	"strings"
	"time"
)

type options struct {
	command         string
	commandExplicit bool
	help            bool
	version         bool
	exitStatus      bool
	expression      string
	expressionSet   bool
	fromFile        string
	indent          int
	inplace         bool
	inputFormat     string
	inputFormatSet  bool
	outputFormat    string
	outputFormatSet bool
	pretty          bool
	noDoc           bool
	nulOutput       bool
	nullInput       bool
	unwrapScalar    bool
	shellKeySep     string
	propertiesSep   string
	disableEnvOps   bool
	disableFileOps  bool
	csvSeparator    rune
	verbose         bool
}

func defaultOptions() options {
	return options{
		command:       "eval",
		indent:        2,
		inputFormat:   "auto",
		outputFormat:  "auto",
		unwrapScalar:  true,
		shellKeySep:   "_",
		propertiesSep: " = ",
		csvSeparator:  ',',
	}
}

func run() {
	os.Exit(runMain(os.Args[1:], os.Stdin, os.Stdout, os.Stderr))
}

func runMain(args []string, stdin *os.File, stdout, stderr io.Writer) int {
	opts := defaultOptions()

	if len(args) > 0 {
		switch args[0] {
		case "help":
			return runHelp(args[1:], stdout, stderr)
		case "eval", "e":
			opts.command = "eval"
			opts.commandExplicit = true
			args = args[1:]
		case "eval-all", "ea":
			opts.command = "eval-all"
			opts.commandExplicit = true
			args = args[1:]
		case "completion", "shell-completion":
			opts.command = "completion"
			opts.commandExplicit = true
			args = args[1:]
		}
	}

	nonFlags, err := parseFlags(args, &opts)
	if err != nil {
		fmt.Fprintf(stderr, "Error: %s\n", err.Error())
		if opts.commandExplicit {
			switch opts.command {
			case "eval":
				_, _ = io.WriteString(stderr, evalHelp)
			case "eval-all":
				_, _ = io.WriteString(stderr, evalAllHelp)
			case "completion":
				_, _ = io.WriteString(stderr, completionHelp)
			}
		} else {
			_, _ = io.WriteString(stderr, rootHelp)
		}
		return 1
	}

	if opts.version {
		_, _ = io.WriteString(stdout, versionString)
		return 0
	}

	if opts.help {
		switch opts.command {
		case "eval":
			_, _ = io.WriteString(stdout, evalHelp)
		case "eval-all":
			_, _ = io.WriteString(stdout, evalAllHelp)
		case "completion":
			_, _ = io.WriteString(stdout, completionHelp)
		default:
			_, _ = io.WriteString(stdout, rootHelp)
		}
		return 0
	}

	switch opts.command {
	case "completion":
		return runCompletion(nonFlags, stdout)
	case "eval", "eval-all":
		return runEval(opts, nonFlags, stdin, stdout, stderr)
	default:
		_, _ = io.WriteString(stdout, rootHelp)
		return 0
	}
}

func runHelp(args []string, stdout, stderr io.Writer) int {
	if len(args) == 0 {
		_, _ = io.WriteString(stdout, rootHelp)
		return 0
	}
	switch args[0] {
	case "eval", "e":
		_, _ = io.WriteString(stdout, evalHelp)
	case "eval-all", "ea":
		_, _ = io.WriteString(stdout, evalAllHelp)
	case "completion", "shell-completion":
		_, _ = io.WriteString(stdout, completionHelp)
	default:
		fmt.Fprintf(stderr, "Error: unknown help topic %q\n", args[0])
		return 1
	}
	return 0
}

func runCompletion(args []string, stdout io.Writer) int {
	if len(args) == 0 {
		_, _ = io.WriteString(stdout, completionHelp)
		return 0
	}
	switch args[0] {
	case "bash":
		_, _ = io.WriteString(stdout, bashCompletion)
	case "zsh":
		_, _ = io.WriteString(stdout, zshCompletion)
	case "fish":
		_, _ = io.WriteString(stdout, fishCompletion)
	case "powershell":
		_, _ = io.WriteString(stdout, powershellCompletion)
	default:
		_, _ = io.WriteString(stdout, completionHelp)
	}
	return 0
}

func runEval(opts options, args []string, stdin *os.File, stdout, stderr io.Writer) int {
	exprText, files, err := resolveExpression(args, opts.expressionSet, opts.expression, opts.fromFile)
	if err != nil {
		fmt.Fprintf(stderr, "Error: %s\n", err.Error())
		return 1
	}

	if opts.inplace && (exprText == "" || len(files) == 0) {
		fmt.Fprintf(stderr, "Error: write in place flag only applicable when giving an expression and at least one file\n")
		return 1
	}

	stdinPiped := isPipedInput(stdin)
	if exprText == "" && !opts.commandExplicit && len(files) == 0 && !stdinPiped && !opts.nullInput {
		_, _ = io.WriteString(stdout, rootHelp)
