	"strings"
	"time"
)

const versionString = "yq (https://github.com/mikefarah/yq/) version v4.52.5"

type options struct {
	command                 string
	explicitCommand         bool
	showHelp                bool
	showVersion             bool
	exitStatus              bool
	inplace                 bool
	indent                  int
	nullInput               bool
	noDoc                   bool
	nulOutput               bool
	prettyPrint             bool
	unwrapScalar            bool
	unwrapScalarExplicit    bool
	inputFormat             string
	inputFormatExplicit     bool
	outputFormat            string
	outputFormatExplicit    bool
	expression              string
	expressionExplicit      bool
	fromFile                string
	shellKeySeparator       string
	propertiesArrayBrackets bool
	propertiesSeparator     string
	luaGlobals              bool
	luaPrefix               string
	luaSuffix               string
	luaUnquoted             bool
	specialHelpOnly         bool
	ignoreNextAsValue       bool
}

func (o options) unwrapScalarValue(yamlDefault bool) bool {
	if o.unwrapScalarExplicit {
		return o.unwrapScalar
	}
	return yamlDefault
}

func main() {
	opts, pos, err := parseCLI(os.Args[1:])
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error: %s\n", err.Error())
		if errors.Is(err, errUnknownFlag) {
			fmt.Fprint(os.Stderr, rootHelpBody)
		}
		os.Exit(1)
	}
	if opts.showVersion {
		fmt.Println(versionString)
		return
	}
	if opts.specialHelpOnly {
		fmt.Print(evalHelpBody)
		return
	}
	if opts.showHelp {
		printHelp(opts)
		return
	}
	if opts.command == "completion" {
		if err := runCompletion(pos); err != nil {
			fmt.Fprintf(os.Stderr, "Error: %s\n", err.Error())
			os.Exit(1)
		}
		return
	}
	expr, files, ok, err := resolveExpressionAndFiles(opts, pos)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error: %s\n", err.Error())
		os.Exit(1)
	}
	if !ok {
		if opts.explicitCommand || len(os.Args[1:]) > 0 {
			if opts.command == "eval-all" {
				fmt.Print(evalAllHelpBody)
			} else {
				fmt.Print(evalHelpBody)
			}
		} else {
			fmt.Print(rootHelpBody)
		}
		return
	}
	docs, err := loadInputs(opts, files)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error: %s\n", err.Error())
		os.Exit(1)
	}
	results, err := evaluate(opts, expr, docs)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error: %s\n", err.Error())
		os.Exit(1)
	}
	if opts.inplace {
		if err := writeInPlace(opts, files, results); err != nil {
			fmt.Fprintf(os.Stderr, "Error: %s\n", err.Error())
			os.Exit(1)
		}
	} else {
		if err := writeResults(opts, results); err != nil {
			fmt.Fprintf(os.Stderr, "Error: %s\n", err.Error())
			os.Exit(1)
		}
	}
	if opts.exitStatus && shouldExitNoMatch(results) {
		fmt.Fprintln(os.Stderr, "Error: no matches found")
		os.Exit(1)
	}
}

var errUnknownFlag = errors.New("unknown flag")

func parseCLI(args []string) (options, []string, error) {
	opts := options{
		command:                 "eval",
		indent:                  2,
		inputFormat:             "auto",
		outputFormat:            "auto",
		shellKeySeparator:       "_",
		propertiesSeparator:     " = ",
		luaPrefix:               "return ",
		luaSuffix:               ";\n",
		unwrapScalar:            true,
		unwrapScalarExplicit:    false,
		propertiesArrayBrackets: false,
	}
	if len(args) == 1 && args[0] == "help" {
		opts.specialHelpOnly = true
		return opts, nil, nil
	}
	if len(args) > 0 {
		switch args[0] {
		case "eval", "e":
			opts.command = "eval"
			opts.explicitCommand = true
			args = args[1:]
		case "eval-all", "ea":
			opts.command = "eval-all"
			opts.explicitCommand = true
			args = args[1:]
		case "completion", "shell-completion":
			opts.command = "completion"
			opts.explicitCommand = true
			args = args[1:]
		}
	}
	var pos []string
	for i := 0; i < len(args); i++ {
		arg := args[i]
		if arg == "--" {
			pos = append(pos, args[i+1:]...)
			break
		}
		if strings.HasPrefix(arg, "--") && arg != "--" {
			name, val, hasValue := strings.Cut(arg[2:], "=")
			getVal := func() (string, error) {
				if hasValue {
					return val, nil
				}
				if i+1 >= len(args) {
					return "", fmt.Errorf("flag needs an argument: --%s", name)
				}
				i++
				return args[i], nil
			}
			switch name {
			case "help":
				opts.showHelp = true
			case "version":
				opts.showVersion = true
			case "exit-status":
				opts.exitStatus = true
			case "inplace":
				opts.inplace = true
			case "null-input":
				opts.nullInput = true
			case "no-doc":
				opts.noDoc = true
			case "nul-output":
				opts.nulOutput = true
			case "prettyPrint":
				opts.prettyPrint = true
			case "colors", "no-colors", "verbose", "header-preprocess", "csv-auto-parse", "tsv-auto-parse", "string-interpolation", "debug-node-info", "security-disable-env-ops", "security-disable-file-ops", "security-enable-system-operator", "xml-keep-namespace", "xml-raw-token", "xml-skip-directives", "xml-skip-proc-inst", "xml-strict-mode", "yaml-compact-seq-indent", "yaml-fix-merge-anchor-to-spec":
			case "unwrapScalar":
				if hasValue {
					b, err := strconv.ParseBool(val)
					if err != nil {
						return opts, nil, err
					}
					opts.unwrapScalar = b
				} else {
					opts.unwrapScalar = true
				}
				opts.unwrapScalarExplicit = true
			case "indent":
				v, err := getVal()
				if err != nil {
					return opts, nil, err
				}
				n, err := strconv.Atoi(v)
				if err != nil {
					return opts, nil, err
				}
				opts.indent = n
			case "input-format":
				v, err := getVal()
				if err != nil {
					return opts, nil, err
				}
				opts.inputFormat = v
				opts.inputFormatExplicit = true
			case "output-format":
				v, err := getVal()
				if err != nil {
					return opts, nil, err
				}
				opts.outputFormat = v
				opts.outputFormatExplicit = true
			case "expression":
				v, err := getVal()
				if err != nil {
					return opts, nil, err
				}
				opts.expression = v
				opts.expressionExplicit = true

