package main

import (
	"fmt"
	"strconv"
	"strings"
)

type yamlLine struct {
	indent int
	text   string
	lineNo int
}

func ParseYAMLDocuments(data string) ([]*Value, error) {
	parts := splitYAMLDocuments(data)
	if len(parts) == 0 {
		return nil, nil
	}
	docs := make([]*Value, 0, len(parts))
	for _, part := range parts {
		lines := tokenizeYAML(part)
		if len(lines) == 0 {
			continue
		}
		pos := 0
		value, err := parseYAMLBlock(lines, &pos, lines[0].indent)
		if err != nil {
			return nil, err
		}
		docs = append(docs, value)
	}
	return docs, nil
}

func splitYAMLDocuments(data string) []string {
	if data == "" {
		return nil
	}
	lines := strings.Split(data, "\n")
	parts := []string{}
	current := []string{}
	for _, line := range lines {
		trimmed := strings.TrimSpace(line)
		if trimmed == "---" {
			if len(current) > 0 {
				parts = append(parts, strings.Join(current, "\n"))
				current = nil
			}
			continue
		}
		current = append(current, line)
	}
	if len(current) > 0 {
		parts = append(parts, strings.Join(current, "\n"))
	}
	return parts
}

func tokenizeYAML(doc string) []yamlLine {
	lines := []yamlLine{}
	for idx, raw := range strings.Split(doc, "\n") {
		line := strings.TrimRight(raw, " \t\r")
		if strings.TrimSpace(line) == "" {
			continue
		}
		if strings.HasPrefix(strings.TrimSpace(line), "#") {
			continue
		}
		indent := 0
		for indent < len(line) && line[indent] == ' ' {
			indent++
		}
		lines = append(lines, yamlLine{
			indent: indent,
			text:   stripInlineComment(line[indent:]),
			lineNo: idx + 1,
		})
	}
	return lines
}

func stripInlineComment(line string) string {
	if line == "" {
		return line
	}
	inSingle := false
	inDouble := false
	for i := 0; i < len(line); i++ {
		switch line[i] {
		case '\'':
			if !inDouble {
				inSingle = !inSingle
			}
		case '"':
			if !inSingle && (i == 0 || line[i-1] != '\\') {
				inDouble = !inDouble
			}
		case '#':
			if !inSingle && !inDouble && (i == 0 || line[i-1] == ' ') {
				return strings.TrimRight(line[:i], " ")
			}
		}
	}
	return line
}

func parseYAMLBlock(lines []yamlLine, pos *int, indent int) (*Value, error) {
	if *pos >= len(lines) {
		return NullValue(), nil
	}
	if lines[*pos].indent < indent {
		return NullValue(), nil
	}
	if lines[*pos].indent != indent {
		indent = lines[*pos].indent
	}
	if isSeqLine(lines[*pos].text) {
		return parseYAMLSequence(lines, pos, indent)
	}
	return parseYAMLMapping(lines, pos, indent)
}

func isSeqLine(text string) bool {
	return text == "-" || strings.HasPrefix(text, "- ")
}

func parseYAMLSequence(lines []yamlLine, pos *int, indent int) (*Value, error) {
	items := []*Value{}
	for *pos < len(lines) && lines[*pos].indent == indent && isSeqLine(lines[*pos].text) {
		line := lines[*pos]
		rest := strings.TrimSpace(strings.TrimPrefix(line.text, "-"))
		start := *pos + 1
		end := start
		for end < len(lines) && lines[end].indent > indent {
			end++
		}
		item, err := parseSyntheticBlock(indent+2, rest, line.lineNo, lines[start:end])
		if err != nil {
			return nil, err
		}
		items = append(items, item)
		*pos = end
	}
	return ArrayValue(items), nil
}

func parseSyntheticBlock(indent int, first string, lineNo int, tail []yamlLine) (*Value, error) {
	synthetic := make([]yamlLine, 0, len(tail)+1)
	if first != "" {
		synthetic = append(synthetic, yamlLine{indent: indent, text: first, lineNo: lineNo})
	}
	synthetic = append(synthetic, tail...)
	if len(synthetic) == 0 {
		return NullValue(), nil
	}
	pos := 0
	return parseYAMLBlock(synthetic, &pos, indent)
}

func parseYAMLMapping(lines []yamlLine, pos *int, indent int) (*Value, error) {
	obj := newObject()
	for *pos < len(lines) && lines[*pos].indent == indent && !isSeqLine(lines[*pos].text) {
		line := lines[*pos]
		key, rest, ok := splitMapEntry(line.text)
		if !ok {
			return nil, fmt.Errorf("yaml: invalid mapping at line %d", line.lineNo)
		}
		*pos++
		if rest == "" {
			if *pos < len(lines) && lines[*pos].indent > indent {
				val, err := parseYAMLBlock(lines, pos, lines[*pos].indent)
				if err != nil {
					return nil, err
				}
				obj.Set(key, val)
			} else {
				obj.Set(key, NullValue())
			}
			continue
		}
		if strings.HasPrefix(rest, "[") || strings.HasPrefix(rest, "{") {
			val, err := parseFlowYAML(rest)
			if err != nil {
				return nil, err
			}
			obj.Set(key, val)
			continue
		}
		obj.Set(key, parseLooseScalar(rest))
	}
	return ObjectValue(obj), nil
}

func splitMapEntry(text string) (string, string, bool) {
	inSingle := false
	inDouble := false
	for i := 0; i < len(text); i++ {
		switch text[i] {
		case '\'':
			if !inDouble {
				inSingle = !inSingle
			}
		case '"':
			if !inSingle && (i == 0 || text[i-1] != '\\') {
				inDouble = !inDouble
			}
		case ':':
			if !inSingle && !inDouble {
				key := strings.TrimSpace(text[:i])
				rest := strings.TrimSpace(text[i+1:])
				return key, rest, true
			}
		}
	}
	return "", "", false
}

func parseFlowYAML(text string) (*Value, error) {
	parser := &flowParser{text: text}
	return parser.parse()
}

type flowParser struct {
	text string
	pos  int
}

func (p *flowParser) parse() (*Value, error) {
	p.skipSpaces()
	if p.pos >= len(p.text) {
		return NullValue(), nil
	}
	switch p.text[p.pos] {
	case '[':
		return p.parseArray()
	case '{':
		return p.parseObject()
	default:
		return nil, fmt.Errorf("yaml: unsupported flow value")
	}
}

func (p *flowParser) parseArray() (*Value, error) {
	p.pos++
	items := []*Value{}
	for {
		p.skipSpaces()
		if p.pos >= len(p.text) {
			return nil, fmt.Errorf("yaml: while parsing a flow sequence: did not find expected ',' or ']'")
		}
		if p.text[p.pos] == ']' {
			p.pos++
			return ArrayValue(items), nil
		}
		val, err := p.parseScalarOrNested()
		if err != nil {
			return nil, err
		}
		items = append(items, val)

package main

import (
	"encoding/json"
	"fmt"
	"io"
	"strconv"
	"strings"
)

type Kind int

const (
	NullKind Kind = iota
	BoolKind
	NumberKind
	StringKind
	ArrayKind
	ObjectKind
)

type ScalarStyle int

const (
	StylePlain ScalarStyle = iota
	StyleDoubleQuoted
)

type Value struct {
	Kind   Kind
	Bool   bool
	Number string
	String string
	Style  ScalarStyle
	Array  []*Value
	Object *Object
}

type Pair struct {
	Key   string
	Value *Value
}

type Object struct {
	Pairs []Pair
	index map[string]int
}

func newObject() *Object {
	return &Object{index: map[string]int{}}
}

func NullValue() *Value {
	return &Value{Kind: NullKind}
}

func BoolValue(v bool) *Value {
	return &Value{Kind: BoolKind, Bool: v}
}

func NumberValue(v string) *Value {
	return &Value{Kind: NumberKind, Number: v}
}

func StringValue(v string) *Value {
	return &Value{Kind: StringKind, String: v, Style: StylePlain}
}

func QuotedStringValue(v string) *Value {
	return &Value{Kind: StringKind, String: v, Style: StyleDoubleQuoted}
}

func ArrayValue(items []*Value) *Value {
	return &Value{Kind: ArrayKind, Array: items}
}

func ObjectValue(obj *Object) *Value {
	return &Value{Kind: ObjectKind, Object: obj}
}

func (o *Object) clone() *Object {
	out := newObject()
	for _, pair := range o.Pairs {
		out.Set(pair.Key, pair.Value.Clone())
	}
	return out
}

func (o *Object) Get(key string) (*Value, bool) {
	idx, ok := o.index[key]
	if !ok {
		return nil, false
	}
	return o.Pairs[idx].Value, true
}

func (o *Object) Set(key string, value *Value) {
	if value == nil {
		value = NullValue()
	}
	if idx, ok := o.index[key]; ok {
		o.Pairs[idx].Value = value
		return
	}
	o.index[key] = len(o.Pairs)
	o.Pairs = append(o.Pairs, Pair{Key: key, Value: value})
}

func (o *Object) Keys() []string {
	keys := make([]string, 0, len(o.Pairs))
	for _, pair := range o.Pairs {
		keys = append(keys, pair.Key)
	}
	return keys
}

func (v *Value) Clone() *Value {
	if v == nil {
		return NullValue()
	}
	switch v.Kind {
	case NullKind:
		return NullValue()
	case BoolKind:
		return BoolValue(v.Bool)
	case NumberKind:
		return NumberValue(v.Number)
	case StringKind:
		return &Value{Kind: StringKind, String: v.String, Style: v.Style}
	case ArrayKind:
		items := make([]*Value, 0, len(v.Array))
		for _, item := range v.Array {
			items = append(items, item.Clone())
		}
		return ArrayValue(items)
	case ObjectKind:
		return ObjectValue(v.Object.clone())
	default:
		return NullValue()
	}
}

func (v *Value) Truthy() bool {
	if v == nil {
		return false
	}
	switch v.Kind {
	case NullKind:
		return false
	case BoolKind:
		return v.Bool
	default:
		return true
	}
}

func (v *Value) Equal(other *Value) bool {
	if v == nil {
		v = NullValue()
	}
	if other == nil {
		other = NullValue()
	}
	if v.Kind != other.Kind {
		return false
	}
	switch v.Kind {
	case NullKind:
		return true
	case BoolKind:
		return v.Bool == other.Bool
	case NumberKind:
		return v.Number == other.Number
	case StringKind:
		return v.String == other.String
	case ArrayKind:
		if len(v.Array) != len(other.Array) {
			return false
		}
		for i := range v.Array {
			if !v.Array[i].Equal(other.Array[i]) {
				return false
			}
		}
		return true
	case ObjectKind:
		if len(v.Object.Pairs) != len(other.Object.Pairs) {
			return false
		}
		for i, pair := range v.Object.Pairs {
			otherPair := other.Object.Pairs[i]
			if pair.Key != otherPair.Key || !pair.Value.Equal(otherPair.Value) {
				return false
			}
		}
		return true
	default:
		return false
	}
}

func MergeValues(left, right *Value) *Value {
	if left == nil {
		return right.Clone()
	}
	if right == nil {
		return left.Clone()
	}
	if left.Kind == ObjectKind && right.Kind == ObjectKind {
		out := left.Clone()
		for _, pair := range right.Object.Pairs {
			existing, ok := out.Object.Get(pair.Key)
			if ok {
				out.Object.Set(pair.Key, MergeValues(existing, pair.Value))
			} else {
				out.Object.Set(pair.Key, pair.Value.Clone())
			}
		}
		return out
	}
	if left.Kind == NumberKind && right.Kind == NumberKind {
		lf, lerr := strconv.ParseFloat(left.Number, 64)
		rf, rerr := strconv.ParseFloat(right.Number, 64)
		if lerr == nil && rerr == nil {
			return NumberValue(formatFloat(lf * rf))
		}
	}
	return right.Clone()
}

func formatFloat(v float64) string {
	return strconv.FormatFloat(v, 'f', -1, 64)
}

func parseLooseScalar(raw string) *Value {
	switch raw {
	case "null", "~":
		return NullValue()
	case "true":
		return BoolValue(true)
	case "false":
		return BoolValue(false)
	}
	if len(raw) >= 2 && raw[0] == '"' && raw[len(raw)-1] == '"' {
		unquoted, err := strconv.Unquote(raw)
		if err == nil {
			return QuotedStringValue(unquoted)
		}
	}
	if len(raw) >= 2 && raw[0] == '\'' && raw[len(raw)-1] == '\'' {
		return QuotedStringValue(strings.ReplaceAll(raw[1:len(raw)-1], "''", "'"))
	}
	if isNumberLiteral(raw) {
