func resolveExpressionAndFiles(opts options, pos []string) (string, []string, bool, error) {
	if opts.command == "completion" {
		return "", pos, true, nil
	}
	var expr string
	if opts.expressionExplicit {
		expr = opts.expression
	} else if opts.fromFile != "" {
		data, err := os.ReadFile(opts.fromFile)
		if err != nil {
			return "", nil, false, err
		}
		expr = strings.TrimRight(string(data), "\n")
	}
	files := []string{}
	if expr == "" {
		if len(pos) > 0 {
			if pos[0] == "-" || fileExists(pos[0]) {
				expr = "."
				files = append(files, pos...)
			} else {
				expr = pos[0]
				files = append(files, pos[1:]...)
			}
		}
	} else {
		files = append(files, pos...)
	}
	if expr == "" && opts.nullInput {
		expr = "."
	}
	if expr == "" && stdinHasData() {
		expr = "."
		files = append(files, "-")
	}
	if expr == "" {
		return "", nil, false, nil
	}
	if len(files) == 0 && !opts.nullInput && !stdinHasData() {
		return "", nil, false, nil
	}
	if len(files) == 0 && !opts.nullInput && stdinHasData() {
		files = []string{"-"}
	}
	return expr, files, true, nil
}

