func xmlElemToValue(elem *xmlElem) Value {
	if len(elem.Attrs) == 0 && len(elem.Children) == 0 {
		if elem.Text == "" {
			return ""
		}
		return elem.Text
	}
	obj := &OrderedMap{}
	for _, attr := range elem.Attrs {
		obj.Entries = append(obj.Entries, Entry{Key: "+@" + attr.Name.Local, Value: attr.Value})
	}
	if elem.Text != "" {
		obj.Entries = append(obj.Entries, Entry{Key: "+content", Value: elem.Text})
	}
	grouped := map[string][]Value{}
	order := []string{}
	for _, child := range elem.Children {
		val := xmlElemToValue(child)
		if _, ok := grouped[child.Name]; !ok {
			order = append(order, child.Name)
		}
		grouped[child.Name] = append(grouped[child.Name], val)
	}
	for _, key := range order {
		values := grouped[key]
		if len(values) == 1 {
			obj.Entries = append(obj.Entries, Entry{Key: key, Value: values[0]})
		} else {
			obj.Entries = append(obj.Entries, Entry{Key: key, Value: values})
		}
	}
	return obj
}

func parsePropsBytes(data []byte) (Value, error) {
	root := &OrderedMap{}
	lines := strings.Split(string(data), "\n")
	for _, line := range lines {
		line = strings.TrimSpace(line)
		if line == "" || strings.HasPrefix(line, "#") || strings.HasPrefix(line, "!") {
			continue
		}
		sep := strings.IndexAny(line, "=:")
		if sep < 0 {
			continue
		}
		key := strings.TrimSpace(line[:sep])
		val := strings.TrimSpace(line[sep+1:])
		assignPath(root, strings.Split(key, "."), val)
	}
	return root, nil
}

func parseINIBytes(data []byte) (Value, error) {
	root := &OrderedMap{}
	cur := root
	lines := strings.Split(string(data), "\n")
	for _, line := range lines {
		line = strings.TrimSpace(line)
		if line == "" || strings.HasPrefix(line, ";") || strings.HasPrefix(line, "#") {
			continue
		}
		if strings.HasPrefix(line, "[") && strings.HasSuffix(line, "]") {
			name := strings.TrimSpace(line[1 : len(line)-1])
			sec := &OrderedMap{}
			putEntry(root, name, sec)
			cur = sec
			continue
		}
		sep := strings.IndexAny(line, "=:")
		if sep < 0 {
			continue
		}
		key := strings.TrimSpace(line[:sep])
		val := strings.TrimSpace(line[sep+1:])
		putEntry(cur, key, val)
	}
	return root, nil
}

func putEntry(obj *OrderedMap, key string, value Value) {
	for i := range obj.Entries {
		if obj.Entries[i].Key == key {
			obj.Entries[i].Value = value
			return
		}
	}
	obj.Entries = append(obj.Entries, Entry{Key: key, Value: value})
}

func assignPath(root *OrderedMap, parts []string, value Value) {
	if len(parts) == 0 {
		return
	}
	cur := root
	for i, part := range parts {
		last := i == len(parts)-1
		if last {
			putEntry(cur, part, value)
			return
		}
		var next *OrderedMap
		for j := range cur.Entries {
			if cur.Entries[j].Key == part {
				if existing, ok := cur.Entries[j].Value.(*OrderedMap); ok {
					next = existing
				}
				break
			}
		}
		if next == nil {
			next = &OrderedMap{}
			putEntry(cur, part, next)
		}
		cur = next
	}
}

func normalizeFormat(s string) string {
	switch strings.ToLower(strings.TrimSpace(s)) {
	case "", "auto", "a":
		return "auto"
	case "yaml", "y", "kyaml", "ky":
		return "yaml"
	case "json", "j":
		return "json"
	case "xml", "x":
		return "xml"
	case "props", "p":
		return "props"
	case "shell", "s":
		return "shell"
	case "lua", "l":
		return "lua"
	case "ini", "i":
		return "ini"
	default:
		return strings.ToLower(strings.TrimSpace(s))
	}
}

func autoFormatForPath(path string) string {
	ext := strings.ToLower(filepath.Ext(path))
	switch ext {
	case ".yaml", ".yml":
		return "yaml"
	case ".json":
		return "json"
	case ".xml":
		return "xml"
	case ".properties":
		return "props"
	case ".ini":
		return "ini"
	default:
		return "yaml"
	}
}

func resolvedOutputFormat(opts options, inputFormat, path string) (string, string) {
	if opts.outputFormatExplicit {
		return normalizeFormat(opts.outputFormat), ""
	}
	if opts.inputFormatExplicit {
		out := "yaml"
		if path != "-" {
			auto := autoFormatForPath(path)
			if auto == inputFormat && auto != "yaml" {
				ts := nowWarnTimestamp()
				msg := fmt.Sprintf("time=%s level=WARN msg=\"yq default output is now 'auto' (based on the filename extension). Normally yq would output '%s', but for backwards compatibility 'yaml' has been set. Please use -oy to specify yaml, or drop the -p flag.\"", ts, inputFormat)
				return out, msg
			}
		}
		return out, ""
	}
	if path != "" && path != "-" {
		return autoFormatForPath(path), ""
	}
	return "yaml", ""
}

func serializeValue(v Value, format string, opts options, nullInput bool) ([]byte, error) {
	switch normalizeFormat(format) {
	case "json":
		unwrap := opts.unwrapScalarValue(false)
		if isScalar(v) && unwrap {
			return []byte(rawScalarString(v) + "\n"), nil
		}
		return serializeJSON(v, true), nil
	case "yaml":
		unwrap := opts.unwrapScalarValue(true)
		if isScalar(v) && unwrap {
			if nullInput && v == nil {
				return []byte("\n"), nil
			}
			return []byte(rawScalarString(v) + "\n"), nil
		}
		return serializeYAML(v, opts.indent)
	case "xml":
		return serializeXML(v)
	case "props":
		return []byte(renderProps(v, opts.propertiesSeparator, opts.propertiesArrayBrackets)), nil
	case "shell":
		return []byte(renderShell(v, opts.shellKeySeparator)), nil
	case "ini":
		return []byte(renderINI(v)), nil
	case "lua":
		return []byte(renderLua(v, opts.luaPrefix, opts.luaSuffix, opts.luaUnquoted, opts.luaGlobals)), nil
	default:
		return nil, fmt.Errorf("unsupported output format: %s", format)
	}
}

