func splitLongFlag(raw string) (string, string, bool) {
	if idx := strings.IndexByte(raw, '='); idx >= 0 {
		return raw[:idx], raw[idx+1:], true
	}
	return raw, "", false
}

func applyLongFlag(name, value string, hasValue bool, opts *options, args []string, i *int) error {
	switch name {
	case "help":
		opts.help = true
	case "version":
		opts.version = true
	case "exit-status":
		opts.exitStatus = parseBoolFlag(value, hasValue, true)
	case "expression":
		v, err := nextValue(name, value, hasValue, args, i)
		if err != nil {
			return err
		}
		opts.expression = v
		opts.expressionSet = true
	case "from-file":
		v, err := nextValue(name, value, hasValue, args, i)
		if err != nil {
			return err
		}
		opts.fromFile = v
	case "indent":
		v, err := nextValue(name, value, hasValue, args, i)
		if err != nil {
			return err
		}
		num, err := strconv.Atoi(v)
		if err != nil {
			return err
		}
		opts.indent = num
	case "inplace":
		opts.inplace = parseBoolFlag(value, hasValue, true)
	case "input-format":
		v, err := nextValue(name, value, hasValue, args, i)
		if err != nil {
			return err
		}
		format, err := canonicalFormat(v)
		if err != nil {
			if opts.inputFormatSet && !opts.outputFormatSet {
				return err
			}
			return err
		}
		opts.inputFormat = format
		opts.inputFormatSet = true
	case "output-format":
		v, err := nextValue(name, value, hasValue, args, i)
		if err != nil {
			return err
		}
		format, err := canonicalFormat(v)
		if err != nil {
			return err
		}
		opts.outputFormat = format
		opts.outputFormatSet = true
	case "prettyPrint":
		opts.pretty = parseBoolFlag(value, hasValue, true)
	case "no-doc":
		opts.noDoc = parseBoolFlag(value, hasValue, true)
	case "nul-output":
		opts.nulOutput = parseBoolFlag(value, hasValue, true)
	case "null-input":
		opts.nullInput = parseBoolFlag(value, hasValue, true)
	case "unwrapScalar":
		opts.unwrapScalar = parseBoolFlag(value, hasValue, true)
	case "shell-key-separator":
		v, err := nextValue(name, value, hasValue, args, i)
		if err != nil {
			return err
		}
		opts.shellKeySep = v
	case "properties-separator":
		v, err := nextValue(name, value, hasValue, args, i)
		if err != nil {
			return err
		}
		opts.propertiesSep = v
	case "security-disable-env-ops":
		opts.disableEnvOps = parseBoolFlag(value, hasValue, true)
	case "security-disable-file-ops":
		opts.disableFileOps = parseBoolFlag(value, hasValue, true)
	case "csv-separator":
		v, err := nextValue(name, value, hasValue, args, i)
		if err != nil {
			return err
		}
		if v == "" {
			return fmt.Errorf("flag needs an argument: --%s", name)
		}
		opts.csvSeparator = []rune(v)[0]
	case "verbose":
		opts.verbose = parseBoolFlag(value, hasValue, true)
	case "colors", "no-colors", "front-matter", "header-preprocess", "lua-globals", "lua-prefix", "lua-suffix", "lua-unquoted", "properties-array-brackets", "security-enable-system-operator", "split-exp", "split-exp-file", "string-interpolation", "tsv-auto-parse", "csv-auto-parse", "xml-attribute-prefix", "xml-content-name", "xml-directive-name", "xml-keep-namespace", "xml-proc-inst-prefix", "xml-raw-token", "xml-skip-directives", "xml-skip-proc-inst", "xml-strict-mode", "yaml-compact-seq-indent", "yaml-fix-merge-anchor-to-spec", "debug-node-info":
		// accepted for CLI compatibility
	default:
		return fmt.Errorf("unknown flag: --%s", name)
	}
	return nil
}

func applyShortFlags(raw string, opts *options, args []string, i *int) error {
	for pos := 0; pos < len(raw); pos++ {
		ch := raw[pos]
		rest := raw[pos+1:]
		switch ch {
		case 'h':
			opts.help = true
		case 'V':
			opts.version = true
		case 'e':
			opts.exitStatus = parseBoolFlag(rest, rest != "", true)
			if strings.HasPrefix(rest, "=") {
				return nil
			}
		case 'i':
			opts.inplace = parseBoolFlag(rest, rest != "", true)
			if strings.HasPrefix(rest, "=") {
				return nil
			}
		case 'n':
			opts.nullInput = parseBoolFlag(rest, rest != "", true)
			if strings.HasPrefix(rest, "=") {
				return nil
			}
		case 'N':
			opts.noDoc = parseBoolFlag(rest, rest != "", true)
			if strings.HasPrefix(rest, "=") {
				return nil
			}
		case '0':
			opts.nulOutput = parseBoolFlag(rest, rest != "", true)
			if strings.HasPrefix(rest, "=") {
				return nil
			}
		case 'P':
			opts.pretty = true
		case 'r':
			opts.unwrapScalar = parseBoolFlag(rest, rest != "", true)
			return nil
		case 'v':
			opts.verbose = true
		case 'I':
			value, err := shortValue(rest, "I", args, i)
			if err != nil {
				return err
			}
			num, err := strconv.Atoi(value)
			if err != nil {
				return err
			}
			opts.indent = num
			return nil
		case 'p':
			value, err := shortValue(rest, "p", args, i)
			if err != nil {
				return err
			}
			format, err := canonicalFormat(value)
			if err != nil {
				return err
			}
			opts.inputFormat = format
			opts.inputFormatSet = true
			return nil
		case 'o':
			value, err := shortValue(rest, "o", args, i)
			if err != nil {
				return err
			}
			format, err := canonicalFormat(value)
			if err != nil {
				return err
			}
			opts.outputFormat = format
			opts.outputFormatSet = true
			return nil
		case 'f':
			value, err := shortValue(rest, "f", args, i)
			if err != nil {
				return err
			}
			_ = value
			return nil
		case 's':
			value, err := shortValue(rest, "s", args, i)
			if err != nil {
				return err
			}
			_ = value
			return nil
		case 'C', 'M', 'c':
			// accepted
		default:
			return fmt.Errorf("unknown shorthand flag: '%c' in -%s", ch, raw)
		}
	}
	return nil
}

func shortValue(rest, name string, args []string, i *int) (string, error) {
	if rest != "" {
		return rest, nil
	}
	if *i+1 >= len(args) {
		return "", fmt.Errorf("flag needs an argument: -%s", name)
	}
	*i++
	return args[*i], nil
}

func nextValue(name, value string, hasValue bool, args []string, i *int) (string, error) {
	if hasValue {
		return value, nil
	}
	if *i+1 >= len(args) {
		return "", fmt.Errorf("flag needs an argument: --%s", name)
	}
	*i++
	return args[*i], nil
}

func parseBoolFlag(value string, hasValue bool, fallback bool) bool {
	if !hasValue {
		return fallback
	}
	value = strings.TrimPrefix(value, "=")
	if value == "false" {
		return false
	}
	if value == "true" {
		return true
	}
	return fallback
}

const bashCompletion = "# bash completion for yq\n_complete_yq() { COMPREPLY=( $( compgen -W 'eval eval-all completion help' -- \"${COMP_WORDS[COMP_CWORD]}\" ) ); }\ncomplete -F _complete_yq yq\n"
const zshCompletion = "#compdef yq\n_arguments '1: :((eval eval-all completion help))'\n"
const fishCompletion = "complete -c yq -f -a 'eval eval-all completion help'\n"
const powershellCompletion = "Register-ArgumentCompleter -CommandName yq -ScriptBlock { param($wordToComplete) 'eval','eval-all','completion','help' | Where-Object { $_ -like \"$wordToComplete*\" } }\n"

		_, _ = io.WriteString(stdout, completionHelp)
	default:
		fmt.Fprintf(stderr, "Error: unknown help topic %q\n", args[0])
		return 1
	}
	return 0
}

func runCompletion(args []string, stdout io.Writer) int {
	if len(args) == 0 {
		_, _ = io.WriteString(stdout, completionHelp)
		return 0
	}
	switch args[0] {
	case "bash":
		_, _ = io.WriteString(stdout, bashCompletion)
	case "zsh":
		_, _ = io.WriteString(stdout, zshCompletion)
	case "fish":
		_, _ = io.WriteString(stdout, fishCompletion)
	case "powershell":
		_, _ = io.WriteString(stdout, powershellCompletion)
	default:
		_, _ = io.WriteString(stdout, completionHelp)
	}
	return 0
}

func runEval(opts options, args []string, stdin *os.File, stdout, stderr io.Writer) int {
	exprText, files, err := resolveExpression(args, opts.expressionSet, opts.expression, opts.fromFile)
	if err != nil {
		fmt.Fprintf(stderr, "Error: %s\n", err.Error())
		return 1
	}

	if opts.inplace && (exprText == "" || len(files) == 0) {
		fmt.Fprintf(stderr, "Error: write in place flag only applicable when giving an expression and at least one file\n")
		return 1
	}

	stdinPiped := isPipedInput(stdin)
	if exprText == "" && !opts.commandExplicit && len(files) == 0 && !stdinPiped && !opts.nullInput {
		_, _ = io.WriteString(stdout, rootHelp)
		return 0
	}
	if exprText != "" && len(files) == 0 && !stdinPiped && !opts.nullInput {
		if opts.command == "eval-all" {
			_, _ = io.WriteString(stdout, evalAllHelp)
		} else {
			_, _ = io.WriteString(stdout, evalHelp)
		}
		return 0
	}

	if opts.inputFormatSet && !opts.outputFormatSet && opts.inputFormat != "auto" && opts.inputFormat != "yaml" {
		_, _ = io.WriteString(stderr, formatWarning(opts.inputFormat))
	}

	var expr Expr
	if exprText != "" {
		expr, err = ParseExpression(exprText)
		if err != nil {
			fmt.Fprintf(stderr, "Error: %s\n", err.Error())
			return 1
		}
	} else {
		expr = &IdentityExpr{}
	}

	stdinData, err := readStdinIfNeeded(stdinPiped, files)
	if err != nil {
		fmt.Fprintf(stderr, "Error: %s\n", err.Error())
		return 1
	}

	stream, sourceFormat, emptyPipedInput, err := buildInputStream(opts, files, stdinData)
	if err != nil {
		fmt.Fprintf(stderr, "Error: %s\n", err.Error())
		return 1
	}

	if opts.nullInput && exprText != "" {
		stream = []EvalCtx{{Current: NullValue()}}
	}
	if !opts.nullInput && exprText != "" && len(stream) == 0 && stdinPiped && emptyPipedInput {
		stream = []EvalCtx{{Current: NullValue(), Meta: Meta{Filename: "-"}}}
	}

	rt := &Runtime{
		InputFormat:    firstNonAuto(opts.inputFormat, sourceFormat),
		DisableEnvOps:  opts.disableEnvOps,
		DisableFileOps: opts.disableFileOps,
	}

	results, err := evaluateCommand(opts.command, expr, stream, rt)
	if err != nil {
		fmt.Fprintf(stderr, "Error: %s\n", err.Error())
		return 1
	}

	outputFormat := resolveOutputFormat(opts, sourceFormat)
	if outputFormat == "auto" {
		outputFormat = "yaml"
	}

	if opts.inplace {
		target := files[0]
		if target == "-" {
			fmt.Fprintf(stderr, "Error: write in place flag only applicable when giving an expression and at least one file\n")
			return 1
		}
		rendered, err := renderResults(results, outputFormat, opts)
		if err != nil {
			fmt.Fprintf(stderr, "Error: %s\n", err.Error())
			return 1
		}
		if err := os.WriteFile(target, []byte(rendered), 0644); err != nil {
			fmt.Fprintf(stderr, "Error: %s\n", err.Error())
			return 1
		}
		return exitStatusCode(opts.exitStatus, results, stderr)
	}

	rendered, err := renderResults(results, outputFormat, opts)
	if err != nil {
		fmt.Fprintf(stderr, "Error: %s\n", err.Error())
		return 1
	}
	_, _ = io.WriteString(stdout, rendered)
	return exitStatusCode(opts.exitStatus, results, stderr)
}

func resolveExpression(args []string, expressionSet bool, expression string, fromFile string) (string, []string, error) {
	if fromFile != "" {
		data, err := os.ReadFile(fromFile)
		if err != nil {
			return "", nil, err
		}
		return strings.TrimRight(string(data), "\n"), args, nil
	}
	if expressionSet {
		return expression, args, nil
	}
	if len(args) == 0 {
		return "", nil, nil
	}
	if args[0] == "-" {
		return "", args, nil
	}
	if _, err := os.Stat(args[0]); err == nil {
		return "", args, nil
	}
	return args[0], args[1:], nil
}

func readStdinIfNeeded(stdinPiped bool, files []string) ([]byte, error) {
	if !stdinPiped {
		return nil, nil
	}
	if len(files) == 0 || containsDash(files) {
		return io.ReadAll(os.Stdin)
	}
	return nil, nil
}

func buildInputStream(opts options, files []string, stdinData []byte) ([]EvalCtx, string, bool, error) {
	stream := []EvalCtx{}
	sourceFormat := ""
	emptyPipedInput := false
	fileIndex := 0

	if opts.nullInput {
		return nil, "yaml", false, nil
	}

	if len(files) == 0 {
		if len(stdinData) == 0 {
			return nil, detectConfiguredInputFormat(opts, "-"), true, nil
		}
		format := detectConfiguredInputFormat(opts, "-")
		values, err := parseDocuments(stdinData, format, "-")
		if err != nil {
			return nil, "", false, err
		}
		if sourceFormat == "" {
			sourceFormat = format
		}
		for docIndex, value := range values {
			stream = append(stream, EvalCtx{Current: value, Meta: Meta{FileIndex: fileIndex, DocumentIndex: docIndex, Filename: "-"}})
		}
		return stream, sourceFormat, false, nil
	}

	stdinUsed := false
	for _, file := range files {
		var data []byte
		if file == "-" {
			stdinUsed = true
			data = stdinData
		} else {
			read, err := os.ReadFile(file)
			if err != nil {
				return nil, "", false, err
			}
			data = read
		}
		format := detectConfiguredInputFormat(opts, file)
		values, err := parseDocuments(data, format, file)
		if err != nil {
			return nil, "", false, err
		}
		if sourceFormat == "" {
			sourceFormat = effectiveSourceFormat(opts, format, file)
		}
		for docIndex, value := range values {
			stream = append(stream, EvalCtx{Current: value, Meta: Meta{FileIndex: fileIndex, DocumentIndex: docIndex, Filename: file}})
		}
		fileIndex++
	}
	if stdinUsed && len(stdinData) == 0 {
		emptyPipedInput = true
	}
	if sourceFormat == "" {
		sourceFormat = "yaml"
	}
	return stream, sourceFormat, emptyPipedInput, nil
}

func detectConfiguredInputFormat(opts options, file string) string {
	if opts.inputFormatSet && opts.inputFormat != "auto" {
		return opts.inputFormat
	}
	if file == "-" {
		return "yaml"
	}
	return detectInputFormat(file)
}

func effectiveSourceFormat(opts options, detected string, file string) string {
	if opts.inputFormatSet && opts.inputFormat != "auto" {
		return "yaml"
	}
	if file == "-" {
		return detected
	}
	return detectInputFormat(file)
}

func resolveOutputFormat(opts options, sourceFormat string) string {
	if opts.outputFormatSet && opts.outputFormat != "auto" {
		return opts.outputFormat
	}
	if opts.inputFormatSet && opts.inputFormat != "auto" {
		return "yaml"
	}
	if sourceFormat == "" {
		return "yaml"
	}
	return sourceFormat
}

func evaluateCommand(command string, expr Expr, stream []EvalCtx, rt *Runtime) ([]EvalCtx, error) {
	if command == "eval-all" {
		return expr.Eval(stream, rt)
	}
	results := []EvalCtx{}
	for _, ctx := range stream {
		out, err := expr.Eval([]EvalCtx{ctx}, rt)
		if err != nil {
			return nil, err
		}
		results = append(results, out...)
	}
	if len(stream) == 0 {
		return expr.Eval(nil, rt)
	}
	return results, nil
}

func renderResults(results []EvalCtx, format string, opts options) (string, error) {
	if len(results) == 0 {
		return "", nil
	}
	chunks := make([]string, 0, len(results))
	for _, result := range results {
		rendered, err := renderValue(result.Current, format, opts.pretty, opts.indent, opts.unwrapScalar && format == "yaml", opts.shellKeySep, opts.propertiesSep)
		if err != nil {
			return "", err
		}
		chunks = append(chunks, rendered)
	}
	if opts.nulOutput {
		trimmed := make([]string, 0, len(chunks))
		for _, chunk := range chunks {
			trimmed = append(trimmed, strings.TrimRight(chunk, "\n"))
		}
		return strings.Join(trimmed, "\x00"), nil
	}
	if format == "yaml" && !opts.noDoc && len(chunks) > 1 {
		var b strings.Builder
		for i, chunk := range chunks {
			if i > 0 {
				b.WriteString("---\n")
			}
			b.WriteString(chunk)
		}
		return b.String(), nil
	}
	return strings.Join(chunks, ""), nil
}

func exitStatusCode(enabled bool, results []EvalCtx, stderr io.Writer) int {
	if !enabled {
		return 0
	}
	for _, result := range results {
		if result.Current.Truthy() {
			return 0
		}
	}
	if len(results) > 0 {
		_, _ = io.WriteString(stderr, "Error: no matches found\n")
	}
	return 1
}

func firstNonAuto(a, b string) string {
	if a != "" && a != "auto" {
		return a
	}
	if b != "" && b != "auto" {
		return b
	}
	return "yaml"
}

func isPipedInput(file *os.File) bool {
	info, err := file.Stat()
	if err != nil {
		return false
	}
	return info.Mode()&os.ModeCharDevice == 0
}

func containsDash(values []string) bool {
	for _, value := range values {
		if value == "-" {
			return true
		}
	}
	return false
}

func formatWarning(name string) string {
	timestamp := time.Now().UTC().Format("2006-01-02T15:04:05.000Z")
	return fmt.Sprintf("time=%s level=WARN msg=\"yq default output is now 'auto' (based on the filename extension). Normally yq would output '%s', but for backwards compatibility 'yaml' has been set. Please use -oy to specify yaml, or drop the -p flag.\"\n", timestamp, name)
}

func parseFlags(args []string, opts *options) ([]string, error) {
	nonFlags := []string{}
	for i := 0; i < len(args); i++ {
		arg := args[i]
		if arg == "--" {
			nonFlags = append(nonFlags, args[i+1:]...)
			break
		}
		if arg == "-" || !strings.HasPrefix(arg, "-") {
			nonFlags = append(nonFlags, arg)
			continue
		}
		if strings.HasPrefix(arg, "--") {
			name, value, hasValue := splitLongFlag(arg[2:])
			if err := applyLongFlag(name, value, hasValue, opts, args, &i); err != nil {
				return nil, err
			}
			continue
		}
		if err := applyShortFlags(arg[1:], opts, args, &i); err != nil {
			return nil, err
		}
	}

	if raw == "" {
		return false
	}
	if raw[0] == '+' || raw[0] == '-' {
		raw = raw[1:]
	}
	if raw == "" {
		return false
	}
	dot := 0
	for _, r := range raw {
		switch {
		case r >= '0' && r <= '9':
		case r == '.':
			dot++
			if dot > 1 {
				return false
			}
		default:
			return false
		}
	}
	return true
}

func ParseJSONValue(data []byte) (*Value, error) {
	dec := json.NewDecoder(strings.NewReader(string(data)))
	dec.UseNumber()
	value, err := parseJSONToken(dec)
	if err != nil {
		return nil, err
	}
	return value, nil
}

func parseJSONToken(dec *json.Decoder) (*Value, error) {
	token, err := dec.Token()
	if err != nil {
		return nil, err
	}
	switch tok := token.(type) {
	case json.Delim:
		switch tok {
		case '{':
			obj := newObject()
			for dec.More() {
				keyTok, err := dec.Token()
				if err != nil {
					return nil, err
				}
				key, ok := keyTok.(string)
				if !ok {
					return nil, fmt.Errorf("invalid json object key")
				}
				val, err := parseJSONToken(dec)
				if err != nil {
					return nil, err
				}
				obj.Set(key, val)
			}
			if _, err := dec.Token(); err != nil {
				return nil, err
			}
			return ObjectValue(obj), nil
		case '[':
			items := []*Value{}
			for dec.More() {
				val, err := parseJSONToken(dec)
				if err != nil {
					return nil, err
				}
				items = append(items, val)
			}
			if _, err := dec.Token(); err != nil {
				return nil, err
			}
			return ArrayValue(items), nil
		default:
			return nil, fmt.Errorf("unexpected json delimiter %q", string(tok))
		}
	case nil:
		return NullValue(), nil
	case bool:
		return BoolValue(tok), nil
	case string:
		return StringValue(tok), nil
	case json.Number:
		return NumberValue(tok.String()), nil
	case float64:
		return NumberValue(formatFloat(tok)), nil
	default:
		return nil, fmt.Errorf("unsupported json token %T", token)
	}
}

func WriteJSON(w io.StringWriter, v *Value, pretty bool, level int, indent int) error {
	if v == nil {
		v = NullValue()
	}
	if pretty {
		return writeJSONPretty(w, v, level, indent)
	}
	return writeJSONCompact(w, v)
}

func writeJSONCompact(w io.StringWriter, v *Value) error {
	switch v.Kind {
	case NullKind:
		_, _ = w.WriteString("null")
	case BoolKind:
		if v.Bool {
			_, _ = w.WriteString("true")
		} else {
			_, _ = w.WriteString("false")
		}
	case NumberKind:
		_, _ = w.WriteString(v.Number)
	case StringKind:
		_, _ = w.WriteString(strconv.Quote(v.String))
	case ArrayKind:
		_, _ = w.WriteString("[")
		for i, item := range v.Array {
			if i > 0 {
				_, _ = w.WriteString(",")
			}
			if err := writeJSONCompact(w, item); err != nil {
				return err
			}
		}
		_, _ = w.WriteString("]")
	case ObjectKind:
		_, _ = w.WriteString("{")
		for i, pair := range v.Object.Pairs {
			if i > 0 {
				_, _ = w.WriteString(",")
			}
			_, _ = w.WriteString(strconv.Quote(pair.Key))
			_, _ = w.WriteString(":")
			if err := writeJSONCompact(w, pair.Value); err != nil {
				return err
			}
		}
		_, _ = w.WriteString("}")
	}
	return nil
}

func writeJSONPretty(w io.StringWriter, v *Value, level int, indent int) error {
	prefix := strings.Repeat(" ", level*indent)
	childPrefix := strings.Repeat(" ", (level+1)*indent)
	switch v.Kind {
	case NullKind, BoolKind, NumberKind, StringKind:
		return writeJSONCompact(w, v)
	case ArrayKind:
		if len(v.Array) == 0 {
			_, _ = w.WriteString("[]")
			return nil
		}
		_, _ = w.WriteString("[\n")
		for i, item := range v.Array {
			if i > 0 {
				_, _ = w.WriteString(",\n")
			}
			_, _ = w.WriteString(childPrefix)
			if err := writeJSONPretty(w, item, level+1, indent); err != nil {
				return err
			}
		}
		_, _ = w.WriteString("\n")
		_, _ = w.WriteString(prefix)
		_, _ = w.WriteString("]")
	case ObjectKind:
		if len(v.Object.Pairs) == 0 {
			_, _ = w.WriteString("{}")
			return nil
		}
		_, _ = w.WriteString("{\n")
		for i, pair := range v.Object.Pairs {
			if i > 0 {
				_, _ = w.WriteString(",\n")
			}
			_, _ = w.WriteString(childPrefix)
			_, _ = w.WriteString(strconv.Quote(pair.Key))
			_, _ = w.WriteString(": ")
			if err := writeJSONPretty(w, pair.Value, level+1, indent); err != nil {
				return err
			}
		}
		_, _ = w.WriteString("\n")
		_, _ = w.WriteString(prefix)
		_, _ = w.WriteString("}")
	}
	return nil
}

