func yamlNodeToValue(node *yaml.Node) Value {
	switch node.Kind {
	case yaml.DocumentNode:
		if len(node.Content) == 0 {
			return nil
		}
		return yamlNodeToValue(node.Content[0])
	case yaml.MappingNode:
		obj := &OrderedMap{}
		for i := 0; i+1 < len(node.Content); i += 2 {
			key := node.Content[i].Value
			obj.Entries = append(obj.Entries, Entry{Key: key, Value: yamlNodeToValue(node.Content[i+1])})
		}
		return obj
	case yaml.SequenceNode:
		out := make([]Value, 0, len(node.Content))
		for _, child := range node.Content {
			out = append(out, yamlNodeToValue(child))
		}
		return out
	case yaml.ScalarNode:
		switch node.Tag {
		case "!!null":
			return nil
		case "!!bool":
			return strings.EqualFold(node.Value, "true")
