		default:
			return nil, fmt.Errorf("unexpected delimiter: %v", t)
		}
	case string:
		return t, nil
	case bool:
		return t, nil
	case nil:
		return nil, nil
	case json.Number:
		if strings.ContainsAny(string(t), ".eE") {
			v, err := t.Float64()
			if err != nil {
				return nil, err
			}
			return v, nil
		}
		v, err := t.Int64()
		if err != nil {
			fv, ferr := t.Float64()
			if ferr != nil {
				return nil, ferr
			}
			return fv, nil
		}
		return v, nil
	default:
		return nil, fmt.Errorf("unsupported json token: %T", tok)
	}
}

type xmlElem struct {
	Name     string
	Attrs    []xml.Attr
	Children []*xmlElem
	Text     string
}

func parseXMLBytes(data []byte) (Value, error) {
	dec := xml.NewDecoder(bytes.NewReader(data))
	var stack []*xmlElem
	var root *xmlElem
	for {
		tok, err := dec.Token()
		if err == io.EOF {
			break
		}
		if err != nil {
			return nil, err
		}
		switch t := tok.(type) {
		case xml.StartElement:
			elem := &xmlElem{Name: t.Name.Local, Attrs: t.Attr}
			if len(stack) > 0 {
				parent := stack[len(stack)-1]
				parent.Children = append(parent.Children, elem)
			} else {
				root = elem
			}
			stack = append(stack, elem)
		case xml.EndElement:
			if len(stack) > 0 {
				stack = stack[:len(stack)-1]
			}
		case xml.CharData:
			if len(stack) == 0 {
				continue
			}
			txt := strings.TrimSpace(string(t))
			if txt == "" {
				continue
			}
			cur := stack[len(stack)-1]
			if cur.Text == "" {
				cur.Text = txt
			} else {
				cur.Text += txt
			}
		}
	}
	if root == nil {
		return &OrderedMap{}, nil

	rendered, err := renderResults(results, outputFormat, opts)
	if err != nil {
		fmt.Fprintf(stderr, "Error: %s\n", err.Error())
		return 1
	}
	_, _ = io.WriteString(stdout, rendered)
	return exitStatusCode(opts.exitStatus, results, stderr)
}

func resolveExpression(args []string, expressionSet bool, expression string, fromFile string) (string, []string, error) {
	if fromFile != "" {
		data, err := os.ReadFile(fromFile)
		if err != nil {
			return "", nil, err
		}
		return strings.TrimRight(string(data), "\n"), args, nil
	}
	if expressionSet {
		return expression, args, nil
	}
	if len(args) == 0 {
		return "", nil, nil
	}
	if looksLikeExpression(args[0]) {
		return args[0], args[1:], nil
	}
	if args[0] == "-" {
		return "", args, nil
	}
	if _, err := os.Stat(args[0]); err == nil {
		return "", args, nil
	}
	return args[0], args[1:], nil
}

func looksLikeExpression(arg string) bool {
	if arg == "." || strings.HasPrefix(arg, ".") || strings.HasPrefix(arg, "[") || strings.HasPrefix(arg, "(") {
		return true
	}
	return strings.ContainsAny(arg, "|=*") || strings.Contains(arg, "select(") || strings.Contains(arg, "load(") || strings.Contains(arg, "strenv(")
}

func readStdinIfNeeded(stdinPiped bool, files []string) ([]byte, error) {
	if !stdinPiped {
		return nil, nil
	}
	if len(files) == 0 || containsDash(files) {
		return io.ReadAll(os.Stdin)
	}
	return nil, nil
}

func buildInputStream(opts options, files []string, stdinData []byte) ([]EvalCtx, string, bool, error) {
	stream := []EvalCtx{}
	sourceFormat := ""
	emptyPipedInput := false
	fileIndex := 0

	if opts.nullInput {
		return nil, "yaml", false, nil
	}

	if len(files) == 0 {
		if len(stdinData) == 0 {
			return nil, detectConfiguredInputFormat(opts, "-"), true, nil
		}
		format := detectConfiguredInputFormat(opts, "-")
		values, err := parseDocuments(stdinData, format, "-")
		if err != nil {
			return nil, "", false, err
		}
		if sourceFormat == "" {
			sourceFormat = format
		}
		for docIndex, value := range values {
			stream = append(stream, EvalCtx{Current: value, Meta: Meta{FileIndex: fileIndex, DocumentIndex: docIndex, Filename: "-"}})
		}
		return stream, sourceFormat, false, nil
	}

	stdinUsed := false
	for _, file := range files {
		var data []byte
		if file == "-" {
			stdinUsed = true
			data = stdinData
		} else {
			read, err := os.ReadFile(file)
			if err != nil {
				return nil, "", false, err
			}
			data = read
		}
		format := detectConfiguredInputFormat(opts, file)
		values, err := parseDocuments(data, format, file)
		if err != nil {
			return nil, "", false, err
		}
		if sourceFormat == "" {
			sourceFormat = effectiveSourceFormat(opts, format, file)
		}
		for docIndex, value := range values {
			stream = append(stream, EvalCtx{Current: value, Meta: Meta{FileIndex: fileIndex, DocumentIndex: docIndex, Filename: file}})
		}
		fileIndex++
	}
	if stdinUsed && len(stdinData) == 0 {
		emptyPipedInput = true
	}
	if sourceFormat == "" {
		sourceFormat = "yaml"
	}
	return stream, sourceFormat, emptyPipedInput, nil
}

func detectConfiguredInputFormat(opts options, file string) string {
	if opts.inputFormatSet && opts.inputFormat != "auto" {
		return opts.inputFormat
	}
	if file == "-" {
		return "yaml"
	}
	return detectInputFormat(file)
}

func effectiveSourceFormat(opts options, detected string, file string) string {
	if opts.inputFormatSet && opts.inputFormat != "auto" {
		return "yaml"
	}
	if file == "-" {
		return detected
	}
	return detectInputFormat(file)
}

func resolveOutputFormat(opts options, sourceFormat string) string {
	if opts.outputFormatSet && opts.outputFormat != "auto" {
		return opts.outputFormat
	}
	if opts.inputFormatSet && opts.inputFormat != "auto" {
		return "yaml"
	}
	if sourceFormat == "" {
		return "yaml"
	}
	return sourceFormat
}

func evaluateCommand(command string, expr Expr, stream []EvalCtx, rt *Runtime) ([]EvalCtx, error) {
	if command == "eval-all" {
		return expr.Eval(stream, rt)
	}
	results := []EvalCtx{}
	for _, ctx := range stream {
		out, err := expr.Eval([]EvalCtx{ctx}, rt)
		if err != nil {
			return nil, err
		}
		results = append(results, out...)
	}
	if len(stream) == 0 {
		return expr.Eval(nil, rt)
	}
	return results, nil
}

func renderResults(results []EvalCtx, format string, opts options) (string, error) {
	if len(results) == 0 {
		return "", nil
	}
	chunks := make([]string, 0, len(results))
	for _, result := range results {
		rendered, err := renderValue(result.Current, format, opts.pretty, opts.indent, opts.unwrapScalar && format == "yaml", opts.shellKeySep, opts.propertiesSep)
		if err != nil {
			return "", err
		}
		chunks = append(chunks, rendered)
	}
	if opts.nulOutput {
		trimmed := make([]string, 0, len(chunks))
		for _, chunk := range chunks {
			trimmed = append(trimmed, strings.TrimRight(chunk, "\n"))
		}
		return strings.Join(trimmed, "\x00"), nil
	}
	if format == "yaml" && !opts.noDoc && len(chunks) > 1 {
		var b strings.Builder
		for i, chunk := range chunks {
			if i > 0 {
				b.WriteString("---\n")
			}
			b.WriteString(chunk)
		}
		return b.String(), nil
	}
	return strings.Join(chunks, ""), nil
}

func exitStatusCode(enabled bool, results []EvalCtx, stderr io.Writer) int {
	if !enabled {
		return 0
	}
	for _, result := range results {
		if result.Current.Truthy() {
			return 0
		}
	}
	if len(results) > 0 {
		_, _ = io.WriteString(stderr, "Error: no matches found\n")
	}
	return 1
}

func firstNonAuto(a, b string) string {
	if a != "" && a != "auto" {
		return a
	}
	if b != "" && b != "auto" {
		return b
	}
	return "yaml"
}

func isPipedInput(file *os.File) bool {
	info, err := file.Stat()
	if err != nil {
		return false
	}
	return info.Mode()&os.ModeCharDevice == 0
}

func containsDash(values []string) bool {
	for _, value := range values {
		if value == "-" {
			return true
		}
	}
	return false
}

func formatWarning(name string) string {
	timestamp := time.Now().UTC().Format("2006-01-02T15:04:05.000Z")
	return fmt.Sprintf("time=%s level=WARN msg=\"yq default output is now 'auto' (based on the filename extension). Normally yq would output '%s', but for backwards compatibility 'yaml' has been set. Please use -oy to specify yaml, or drop the -p flag.\"\n", timestamp, name)
}

