package main

import (
	"fmt"
	"os"
	"strconv"
	"strings"
	"unicode"
)

type Meta struct {
	FileIndex     int
	DocumentIndex int
	Filename      string
}

type EvalCtx struct {
	Current *Value
	Meta    Meta
	Vars    map[string]*Value
}

type Expr interface {
	Eval(stream []EvalCtx, rt *Runtime) ([]EvalCtx, error)
}

type Runtime struct {
	InputFormat    string
	DisableEnvOps  bool
	DisableFileOps bool
}

type LiteralExpr struct {
	Value *Value
}

type IdentityExpr struct{}

type IdentExpr struct {
	Name string
}

type VarExpr struct {
	Name string
}

type PathExpr struct {
	Base     Expr
	Segments []PathSegment
}

type PathSegment struct {
	Kind  string
	Key   string
	Index int
}

type PipeExpr struct {
	Left  Expr
	Right Expr
}

type BinaryExpr struct {
	Op    string
	Left  Expr
	Right Expr
}

type AssignExpr struct {
	Target *PathExpr
	Value  Expr
}

