	Inner Expr
}

type FuncExpr struct {
	Name string
	Args []Expr
}

type IReduceExpr struct {
	Source  Expr
	VarName string
	Init    Expr
	Update  Expr
}

func (e *LiteralExpr) Eval(stream []EvalCtx, rt *Runtime) ([]EvalCtx, error) {
	out := make([]EvalCtx, 0, len(stream))
	for _, ctx := range stream {
		out = append(out, EvalCtx{Current: e.Value.Clone(), Meta: ctx.Meta, Vars: cloneVars(ctx.Vars)})
	}
	if len(stream) == 0 {
		out = append(out, EvalCtx{Current: e.Value.Clone()})
	}
	return out, nil
}

func (e *IdentityExpr) Eval(stream []EvalCtx, rt *Runtime) ([]EvalCtx, error) {
	out := make([]EvalCtx, 0, len(stream))
	for _, ctx := range stream {
		out = append(out, EvalCtx{Current: ctx.Current.Clone(), Meta: ctx.Meta, Vars: cloneVars(ctx.Vars)})
	}
	return out, nil
}

func (e *IdentExpr) Eval(stream []EvalCtx, rt *Runtime) ([]EvalCtx, error) {
	out := make([]EvalCtx, 0, len(stream))
	for _, ctx := range stream {
		switch e.Name {
		case "fileIndex", "fi":
			out = append(out, EvalCtx{Current: NumberValue(strconv.Itoa(ctx.Meta.FileIndex)), Meta: ctx.Meta, Vars: cloneVars(ctx.Vars)})
		case "documentIndex", "di":
			out = append(out, EvalCtx{Current: NumberValue(strconv.Itoa(ctx.Meta.DocumentIndex)), Meta: ctx.Meta, Vars: cloneVars(ctx.Vars)})
		case "filename":
			out = append(out, EvalCtx{Current: StringValue(ctx.Meta.Filename), Meta: ctx.Meta, Vars: cloneVars(ctx.Vars)})
		default:
			out = append(out, EvalCtx{Current: NullValue(), Meta: ctx.Meta, Vars: cloneVars(ctx.Vars)})
		}
	}
	return out, nil
}

func (e *VarExpr) Eval(stream []EvalCtx, rt *Runtime) ([]EvalCtx, error) {
	out := make([]EvalCtx, 0, len(stream))
	for _, ctx := range stream {
		value, ok := ctx.Vars[e.Name]
		if !ok {
			value = NullValue()
		}
		out = append(out, EvalCtx{Current: value.Clone(), Meta: ctx.Meta, Vars: cloneVars(ctx.Vars)})
	}
	return out, nil
}

func (e *PathExpr) Eval(stream []EvalCtx, rt *Runtime) ([]EvalCtx, error) {
	base := e.Base
	if base == nil {
		base = &IdentityExpr{}
	}
	baseResults, err := base.Eval(stream, rt)
	if err != nil {
		return nil, err
	}
	current := baseResults
	for _, segment := range e.Segments {
		next := []EvalCtx{}
		for _, ctx := range current {
			switch segment.Kind {
			case "field":
				switch ctx.Current.Kind {
				case ObjectKind:
					if val, ok := ctx.Current.Object.Get(segment.Key); ok {
						next = append(next, EvalCtx{Current: val.Clone(), Meta: ctx.Meta, Vars: cloneVars(ctx.Vars)})
						continue
					}
					next = append(next, EvalCtx{Current: NullValue(), Meta: ctx.Meta, Vars: cloneVars(ctx.Vars)})
				case ArrayKind:
					index, err := strconv.ParseInt(segment.Key, 10, 64)
					if err != nil {
						return nil, fmt.Errorf("cannot index array with '%s' (%v)", segment.Key, err)
					}
					if int(index) >= 0 && int(index) < len(ctx.Current.Array) {
						next = append(next, EvalCtx{Current: ctx.Current.Array[int(index)].Clone(), Meta: ctx.Meta, Vars: cloneVars(ctx.Vars)})
						continue
					}
					next = append(next, EvalCtx{Current: NullValue(), Meta: ctx.Meta, Vars: cloneVars(ctx.Vars)})
				case NullKind:
					next = append(next, EvalCtx{Current: NullValue(), Meta: ctx.Meta, Vars: cloneVars(ctx.Vars)})
				}
			case "index":
				switch ctx.Current.Kind {
				case ArrayKind:
					if segment.Index >= 0 && segment.Index < len(ctx.Current.Array) {
						next = append(next, EvalCtx{Current: ctx.Current.Array[segment.Index].Clone(), Meta: ctx.Meta, Vars: cloneVars(ctx.Vars)})
						continue
					}
					next = append(next, EvalCtx{Current: NullValue(), Meta: ctx.Meta, Vars: cloneVars(ctx.Vars)})
				case ObjectKind, NullKind:
					next = append(next, EvalCtx{Current: NullValue(), Meta: ctx.Meta, Vars: cloneVars(ctx.Vars)})
				}
			case "iterate":
				if ctx.Current.Kind == ArrayKind {
					for _, item := range ctx.Current.Array {
						next = append(next, EvalCtx{Current: item.Clone(), Meta: ctx.Meta, Vars: cloneVars(ctx.Vars)})
					}
				}
			}
		}
		current = next
	}
	return current, nil
}

func (e *PipeExpr) Eval(stream []EvalCtx, rt *Runtime) ([]EvalCtx, error) {
	left, err := e.Left.Eval(stream, rt)
	if err != nil {
		return nil, err
	}
	return e.Right.Eval(left, rt)
}

func (e *BinaryExpr) Eval(stream []EvalCtx, rt *Runtime) ([]EvalCtx, error) {
	if e.Op == "==" {
		out := make([]EvalCtx, 0, len(stream))
		for _, ctx := range stream {
			left, err := firstValue(e.Left, []EvalCtx{ctx}, rt)
			if err != nil {
				return nil, err
			}
			right, err := firstValue(e.Right, []EvalCtx{ctx}, rt)
			if err != nil {
				return nil, err
			}
			out = append(out, EvalCtx{Current: BoolValue(left.Equal(right)), Meta: ctx.Meta, Vars: cloneVars(ctx.Vars)})
		}
		return out, nil
	}

package main

import (
	"fmt"
	"strconv"
	"strings"
)

type yamlLine struct {
	indent int
	text   string
	lineNo int
}

func ParseYAMLDocuments(data string) ([]*Value, error) {
	parts := splitYAMLDocuments(data)
	if len(parts) == 0 {
		return nil, nil
	}
	docs := make([]*Value, 0, len(parts))
	for _, part := range parts {
		lines := tokenizeYAML(part)
		if len(lines) == 0 {
			continue
		}
		pos := 0
		value, err := parseYAMLBlock(lines, &pos, lines[0].indent)
		if err != nil {
			return nil, err
		}
		docs = append(docs, value)
	}
	return docs, nil
}

func splitYAMLDocuments(data string) []string {
	if data == "" {
		return nil
	}
	lines := strings.Split(data, "\n")
	parts := []string{}
	current := []string{}
	for _, line := range lines {
		trimmed := strings.TrimSpace(line)
		if trimmed == "---" {
			if len(current) > 0 {
				parts = append(parts, strings.Join(current, "\n"))
				current = nil
			}
			continue
		}
		current = append(current, line)
	}
	if len(current) > 0 {
		parts = append(parts, strings.Join(current, "\n"))
	}
	return parts
}

func tokenizeYAML(doc string) []yamlLine {
	lines := []yamlLine{}
	for idx, raw := range strings.Split(doc, "\n") {
		line := strings.TrimRight(raw, " \t\r")
		if strings.TrimSpace(line) == "" {
			continue
		}
		if strings.HasPrefix(strings.TrimSpace(line), "#") {
			continue
		}
		indent := 0
		for indent < len(line) && line[indent] == ' ' {
			indent++
		}
		lines = append(lines, yamlLine{
			indent: indent,
			text:   stripInlineComment(line[indent:]),
			lineNo: idx + 1,
		})
	}
	return lines
}

func stripInlineComment(line string) string {
	if line == "" {
		return line
	}
	inSingle := false
	inDouble := false
	for i := 0; i < len(line); i++ {
		switch line[i] {
		case '\'':
			if !inDouble {
				inSingle = !inSingle
			}
		case '"':
			if !inSingle && (i == 0 || line[i-1] != '\\') {
				inDouble = !inDouble
			}
		case '#':
			if !inSingle && !inDouble && (i == 0 || line[i-1] == ' ') {
				return strings.TrimRight(line[:i], " ")
			}
		}
	}
	return line
}

func parseYAMLBlock(lines []yamlLine, pos *int, indent int) (*Value, error) {
	if *pos >= len(lines) {
		return NullValue(), nil
	}
	if lines[*pos].indent < indent {
		return NullValue(), nil
	}
	if lines[*pos].indent != indent {
		indent = lines[*pos].indent
	}
	if isSeqLine(lines[*pos].text) {
		return parseYAMLSequence(lines, pos, indent)
	}
	if strings.HasPrefix(lines[*pos].text, "[") || strings.HasPrefix(lines[*pos].text, "{") {
		value, err := parseFlowYAML(lines[*pos].text)
		if err != nil {
			return nil, err
		}
		*pos++
		return value, nil
	}
	if _, _, ok := splitMapEntry(lines[*pos].text); ok {
		return parseYAMLMapping(lines, pos, indent)
	}
	value := parseLooseScalar(lines[*pos].text)
	*pos++
	return value, nil
}

func isSeqLine(text string) bool {
	return text == "-" || strings.HasPrefix(text, "- ")
}

func parseYAMLSequence(lines []yamlLine, pos *int, indent int) (*Value, error) {
	items := []*Value{}
	for *pos < len(lines) && lines[*pos].indent == indent && isSeqLine(lines[*pos].text) {
		line := lines[*pos]
		rest := strings.TrimSpace(strings.TrimPrefix(line.text, "-"))
		start := *pos + 1
		end := start
		for end < len(lines) && lines[end].indent > indent {
			end++
		}
		item, err := parseSyntheticBlock(indent+2, rest, line.lineNo, lines[start:end])
		if err != nil {
			return nil, err
		}
		items = append(items, item)
		*pos = end
	}
	return ArrayValue(items), nil
}

func parseSyntheticBlock(indent int, first string, lineNo int, tail []yamlLine) (*Value, error) {
	synthetic := make([]yamlLine, 0, len(tail)+1)
	if first != "" {
		synthetic = append(synthetic, yamlLine{indent: indent, text: first, lineNo: lineNo})
	}
	synthetic = append(synthetic, tail...)
	if len(synthetic) == 0 {
		return NullValue(), nil
	}
	pos := 0
	return parseYAMLBlock(synthetic, &pos, indent)
}

func parseYAMLMapping(lines []yamlLine, pos *int, indent int) (*Value, error) {
	obj := newObject()
	for *pos < len(lines) && lines[*pos].indent == indent && !isSeqLine(lines[*pos].text) {
		line := lines[*pos]
		key, rest, ok := splitMapEntry(line.text)
		if !ok {
			return nil, fmt.Errorf("yaml: invalid mapping at line %d", line.lineNo)
		}
		*pos++
		if rest == "" {
			if *pos < len(lines) && lines[*pos].indent > indent {
				val, err := parseYAMLBlock(lines, pos, lines[*pos].indent)
				if err != nil {
					return nil, err
				}
				obj.Set(key, val)
			} else {
				obj.Set(key, NullValue())
			}
			continue
		}
		if strings.HasPrefix(rest, "[") || strings.HasPrefix(rest, "{") {
			val, err := parseFlowYAML(rest)
			if err != nil {
				return nil, err
			}
			obj.Set(key, val)
			continue
		}
		obj.Set(key, parseLooseScalar(rest))
	}
	return ObjectValue(obj), nil
}

func splitMapEntry(text string) (string, string, bool) {
	inSingle := false
	inDouble := false
	for i := 0; i < len(text); i++ {
		switch text[i] {
		case '\'':
			if !inDouble {
				inSingle = !inSingle
			}
		case '"':
			if !inSingle && (i == 0 || text[i-1] != '\\') {
				inDouble = !inDouble
			}
		case ':':
			if !inSingle && !inDouble {
				key := strings.TrimSpace(text[:i])
				rest := strings.TrimSpace(text[i+1:])
				return key, rest, true
			}
		}
	}
	return "", "", false
}

func parseFlowYAML(text string) (*Value, error) {
	parser := &flowParser{text: text}
	return parser.parse()
}

type flowParser struct {
	text string
	pos  int
}

func (p *flowParser) parse() (*Value, error) {
	p.skipSpaces()
	if p.pos >= len(p.text) {
		return NullValue(), nil
	}
	switch p.text[p.pos] {
	case '[':
		return p.parseArray()
	case '{':
		return p.parseObject()
	default:
		return nil, fmt.Errorf("yaml: unsupported flow value")
	}
}

func (p *flowParser) parseArray() (*Value, error) {
	p.pos++
	items := []*Value{}
	for {
