func isNumberLiteral(raw string) bool {
	if raw == "" {
		return false
	}
	if raw[0] == '+' || raw[0] == '-' {
		raw = raw[1:]
	}
	if raw == "" {
		return false
	}
	dot := 0
	for _, r := range raw {
		switch {
		case r >= '0' && r <= '9':
		case r == '.':
			dot++
			if dot > 1 {
				return false
			}
		default:
			return false
		}
	}
	return true
}

