		return "", fmt.Errorf("unknown format '%s'", raw)
	}
}

func detectInputFormat(path string) string {
	switch strings.ToLower(filepath.Ext(path)) {
	case ".yaml", ".yml":
		return "yaml"
	case ".json":
		return "json"
	case ".xml":
		return "xml"
	case ".properties":
		return "props"
	case ".ini":
		return "ini"
	default:
		return "yaml"
	}
}

func parseDocuments(data []byte, format string, source string) ([]*Value, error) {
	switch format {
	case "", "auto":
		if source != "" && source != "-" {
			format = detectInputFormat(source)
		} else {
			format = "yaml"
		}
	}
	switch format {
	case "yaml":
		return ParseYAMLDocuments(string(data))
	case "json":
		value, err := ParseJSONValue(data)
		if err != nil {
			return nil, err
		}
		return []*Value{value}, nil
	case "xml":
		value, err := parseXMLValue(data)
		if err != nil {
			return nil, err
		}
		return []*Value{value}, nil
	case "props":
		return []*Value{parsePropsValue(data)}, nil
	case "ini":
		return []*Value{parseINIValue(data)}, nil
	case "base64":
		decoded, err := base64.StdEncoding.DecodeString(strings.TrimSpace(string(data)))
		if err != nil {
			return nil, err
		}
		return []*Value{StringValue(string(decoded))}, nil
	case "uri":
		decoded, err := url.QueryUnescape(strings.TrimSpace(string(data)))
		if err != nil {
			return nil, err
		}
		return []*Value{StringValue(decoded)}, nil
	default:
		return nil, fmt.Errorf("unsupported input format: %s", format)
	}
}

func loadSingleValue(path string, inputFormat string) (*Value, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, err
	}
	format := detectInputFormat(path)
	if format == "yaml" && inputFormat != "" && inputFormat != "auto" {
		format = inputFormat
	}
	values, err := parseDocuments(data, format, path)
	if err != nil {
		return nil, err
	}
	if len(values) == 0 {
		return NullValue(), nil
	}
	if len(values) == 1 {
		return values[0], nil
	}
	return ArrayValue(values), nil
}

func renderValue(v *Value, format string, pretty bool, indent int, unwrapScalar bool, shellKeySep string, propertiesSep string) (string, error) {
	switch format {
	case "", "auto", "yaml":
		return RenderYAMLDocument(v, indent, pretty, unwrapScalar), nil
	case "json":
		var b strings.Builder
		if err := WriteJSON(&b, v, true, 0, indent); err != nil {
			return "", err
		}
		b.WriteByte('\n')
		return b.String(), nil
	case "xml":
		return renderXMLValue(v)
	case "props":
		return renderPropsValue(v, propertiesSep, false), nil
	case "shell":
		return renderShellValue(v, shellKeySep), nil
	case "ini":
		return renderINIValue(v), nil
	case "lua":
		return renderLuaValue(v, "return ", ";\n", false, false), nil
	case "base64":
		return base64.StdEncoding.EncodeToString([]byte(renderScalarAsString(v))) + "\n", nil
	case "uri":
		return url.QueryEscape(renderScalarAsString(v)) + "\n", nil
	default:
		return "", fmt.Errorf("unsupported output format: %s", format)
	}
}

